    with open(path, newline='', encoding='cp1252') as f:
        reader = csv.DictReader(f)
        file_rows = [clean_row(r) for r in reader]
    seen = set()
    file_txns = []
    for r in file_rows:
        tid = r['id']
        if tid in seen:
