"""Parsing helpers for ERP export rows."""

from datetime import datetime
from decimal import Decimal

from ledger.models import Transaction


def parse_amount(text: str) -> Decimal:
    """Parse an accounting-style amount such as ``1,234.50``."""
    s = text.strip().replace(",", "")
    if s.startswith("(") and s.endswith(")"):
        return -Decimal(s[1:-1].strip())
    if s.startswith("-"):
        return -Decimal(s[1:].strip())
    if s.startswith("+"):
        return Decimal(s[1:].strip())
    return Decimal(s)


def parse_timestamp(text: str) -> datetime:
    return datetime.fromisoformat(text.strip())


def parse_rows(rows, seen=None):
    """Turn raw CSV rows into Transactions, dropping repeated ids."""
    if seen is None:
        seen = set()
    transactions = []
    for row in rows:
        txn = Transaction.from_row(row)
        if txn.txn_id in seen:
            continue
        seen.add(txn.txn_id)
        transactions.append(txn)
    return transactions
